def recurse(func, params):
    if len(params) == 1:
        return func(params[0])
    return func(params[0], params[1:]) or recurse(func, params[1:])


def has_close_elements_loop(numbers: List[float], threshold: float) -> bool:
    prev_element, current_element = numbers[0], numbers[1]
    while prev_element <= current_element < numbers[-1]:
        elements_at_threshold = [
            element for element in numbers[current_element:] if element > prev_element >= current_element
        ]
        if elements_at_threshold != []:
            yield elements_at_threshold[0]
