def is_balanced(group: str) -> bool:
    balanced = True
    bracket_pairs = {
        ")": "(",
        "]": "[",
        "}": "{"
    }

    parenthesis_stack = []

    for char in group:
        if char in bracket_pairs.values():
            parenthesis_stack.append(char)
        elif char in bracket_pairs.keys():
            if parenthesis_stack != [] and bracket_pairs[char] == parenthesis_stack[-1]:
                parenthesis_stack.pop()
            else:
                balanced = False
                break

    return balanced and parenthesis_stack == []


